Here’s a concise TypeScript implementation:

```ts
/**
 * Returns the FizzBuzz representation of a number.
 *
 * @param n - The input number.
 * @returns "FizzBuzz" if n is divisible by both 3 and 5,
 *          "Fizz" if only divisible by 3,
 *          "Buzz" if only divisible by 5,
 *          otherwise the number itself as a string.
 */
export function fizzbuzz(n: number): string {
    const divisibleBy3 = n % 3 === 0;
    const divisibleBy5 = n % 5 === 0;

    if (divisibleBy3 && divisibleBy5) return "FizzBuzz";
    if (divisibleBy3) return "Fizz";
    if (divisibleBy5) return "Buzz";

    return n.toString();
}
```

You can test it quickly:

```ts
console.log([1, 3, 5, 15, 16].map(fizzbuzz));
// Output: ["1", "Fizz", "Buzz", "FizzBuzz", "16"]
```

